import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { getById } from "../services/schemeService";

const SchemeDetails = () => {

  const { id } = useParams();
  const navigate = useNavigate();

  const [scheme, setScheme] = useState(null);
  const [lang, setLang] = useState(localStorage.getItem("lang") || "en");

  useEffect(() => {
    fetchScheme();
  }, [id, lang]);

  const fetchScheme = async () => {
    const data = await getById(id, lang);
    setScheme(data);
  };

  if (!scheme) return <h2>Loading...</h2>;

  return (
    <div className="details-container">

      <button onClick={() => navigate(-1)} className="back-btn">
        ← Back
      </button>

      <h2>{scheme.schemeName}</h2>

      <img src={scheme.image} alt="" />

      <div className="section">
        <h3>📌 Description</h3>
        <p>{scheme.description}</p>
      </div>

      <div className="section highlight">
        <h3>💰 Benefits</h3>
        <p>{scheme.benefits}</p>
      </div>

      <div className="section">
        <h3>✅ Eligibility</h3>
        <p>{scheme.eligibility}</p>
      </div>

      <div className="section">
        <h3>📄 Documents</h3>
        <p>{scheme.requiredDocuments}</p>
      </div>

      <a href={scheme.officialLink} target="_blank" className="apply-btn">
        Apply Now 🚀
      </a>

    </div>
  );
};

export default SchemeDetails;
